%[text] # Build an airfoil from its CST parameters
%[text] Move a slider and the airfoil is rebuilt with `CST2Airfoil` (the second section runs again).
%[text] Each side is (Kulfan 2008, Eq. 17-19) `z/c = C(psi)*S(psi) + psi*dz`, with `psi = x/c`,
%[text] Meaning of the coefficients:
%[text] Default values: NACA 2412, from `Airfoil2CST(Airfoil_class.naca4("2412"),n=4)`.
%[text] ## Setup
clc; clear; close all
addpath(fullfile('..','src'))       % matlab_cst functions (run from the examples folder)

% plot settings
axFS = 13;
axFN = "Times New Roman";
lw   = 2;
axlw = 1.25;
set(0, 'defaultAxesTickLabelInterpreter','latex', ...
       'defaultTextInterpreter','latex', ...
       'DefaultLegendInterpreter','latex');
%%
%[text] ## CST parameters
Au = zeros(5,1); Al = zeros(5,1);
% upper side coefficients
Au(1) = 0.171; %[control:slider:7545]{"position":[9,14]}
Au(2) = 0.24; %[control:slider:e6cd]{"position":[9,13]}
Au(3) = 0.168; %[control:slider:0113]{"position":[9,14]}
Au(4) = 0.222; %[control:slider:674e]{"position":[9,14]}
Au(5) = 0.2; %[control:slider:1481]{"position":[9,12]}
% lower side coefficients
Al(1) = -0.171; %[control:slider:7edb]{"position":[9,15]}
Al(2) = -0.067; %[control:slider:5270]{"position":[9,15]}
Al(3) = -0.139; %[control:slider:d137]{"position":[9,15]}
Al(4) = -0.049; %[control:slider:8b84]{"position":[9,15]}
Al(5) = -0.097; %[control:slider:866f]{"position":[9,15]}
% trailing edge z/c of the two sides
dzu = 0; %[control:slider:1f0d]{"position":[7,8]}
dzl = 0; %[control:slider:c3fc]{"position":[7,8]}
% class function exponents
N1 = 0.45; %[control:slider:cc7f]{"position":[6,10]}
N2 = 1; %[control:slider:2e5f]{"position":[6,7]}

% BUILD ---------------------------------------------------------------------
CST = struct('Au',Au,'Al',Al,'dzu',dzu,'dzl',dzl,'N1',N1,'N2',N2);
AF  = CST2Airfoil(CST,201,name="CST airfoil");
[tmax,x_tmax] = AF.thickness();
fprintf('t/c = %.4f at x/c = %.3f | r_LE/c: upper %.4f, lower %.4f | TE thickness %.4f\n', ... %[output:group:90a9fc36] %[output:374f8387]
        tmax,x_tmax,Au(1)^2/2,Al(1)^2/2,dzu - dzl); %[output:group:90a9fc36] %[output:374f8387]

% PLOT ----------------------------------------------------------------------
% The figure is drawn once (first run) and then only its lines are updated:
% drawing a figure from scratch (layout, legends, labels) takes seconds, an
% update a fraction of a second. Run the Setup section to start from scratch.
psi   = cosineSpacing(201);
B     = bernsteinBasis(psi,numel(Au)-1);    % Bernstein polynomials, one per column
C     = classFunction(psi,N1,N2);
compU = C.*B.*Au';                          % component airfoils (Kulfan Fig. 7)
compL = C.*B.*Al';
zt    = interp1(psi,[cstCurve(psi,Al,dzl,N1,N2) cstCurve(psi,Au,dzu,N1,N2)],x_tmax);
if ~exist('hp','var') || ~isstruct(hp) || ~isgraphics(hp.fig)
    hp.fig = figure('Position',[100 100 800 700]);
    tiledlayout(hp.fig,2,1,'TileSpacing','compact');
    % airfoil and its component airfoils
    ax1 = nexttile; hold on
    hp.compU = plot(psi,compU,'Color',[0.55 0.65 0.95],'LineWidth',0.75,'HandleVisibility','off');
    hp.compL = plot(psi,compL,'Color',[0.95 0.6 0.55],'LineWidth',0.75,'HandleVisibility','off');
    hp.AF    = plot(AF.x,AF.z,'k-','LineWidth',lw,'DisplayName','airfoil');
    hp.t     = plot(x_tmax*[1 1],zt,'k--');
    xlabel('$x/c$'); ylabel('$z/c$'); xlim([0 1]); ylim([-0.25 0.25]);
    legend('Location','northeast'); styleAx(ax1,axFS,axFN,axlw);
    % shape functions: smooth and almost straight for any real airfoil (Kulfan Fig. 1, 9)
    ax2 = nexttile; hold on
    hp.SU  = plot(psi,B*Au,'b-','LineWidth',lw,'DisplayName','$S_u$');
    hp.SL  = plot(psi,-B*Al,'r-','LineWidth',lw,'DisplayName','$-S_l$');
    hp.SUr = plot(psi,B.*Au','b:','LineWidth',1,'HandleVisibility','off');
    hp.SLr = plot(psi,-B.*Al','r:','LineWidth',1,'HandleVisibility','off');
    xlabel('$\psi = x/c$'); ylabel('$S(\psi)$'); xlim([0 1]);
    legend('Location','northeast'); styleAx(ax2,axFS,axFN,axlw);
end
% update the lines
for r = 1:numel(Au)
    hp.compU(r).YData = compU(:,r);   hp.compL(r).YData = compL(:,r); %[output:5ee1ab72]
    hp.SUr(r).YData   = B(:,r)*Au(r); hp.SLr(r).YData   = -B(:,r)*Al(r);
end
set(hp.AF,'XData',AF.x,'YData',AF.z); %[output:5ee1ab72]
set(hp.t,'XData',x_tmax*[1 1],'YData',zt,'DisplayName',sprintf('$t/c = %.3f$',tmax)); %[output:5ee1ab72]
hp.SU.YData = B*Au; %[output:5ee1ab72]
hp.SL.YData = -B*Al; %[output:5ee1ab72]
figure(hp.fig);                             % show it as the output of this section
%%
%[text] ## Local functions
function styleAx(ax,axFS,axFN,axlw)
% axes style of the script skeleton
ax.FontName  = axFN;
ax.FontSize  = axFS;
ax.LineWidth = axlw;
ax.XMinorTick = "on"; ax.YMinorTick = "on";
ax.Layer = "top";
box(ax,'on'); grid(ax,'on');
ax.GridAlpha = 0.1;
end

